/* Kelas VIII - Semester 2 - Muamalah (Jual Beli, Khiyar, Qirad)
   10 PGK (2 jawaban benar) + 10 Benar/Salah + 10 Jawaban Singkat + 5 Esai.
   Semua soal HOTS, original, selaras KMA 183/2019. */
window.BSAddTypes({
'id':'k8-muamalah',
'pgk':[
{level:'HOTS',indicator:'Menganalisis dua pernyataan yang tepat tentang kejujuran dan pencatatan dalam perdagangan',text:'Seorang pedagang di pasar selalu menepati timbangan, menjelaskan cacat barang kepada pembeli, dan mencatat setiap transaksi yang tidak tunai dalam buku pembukuan. Pilihlah dua pernyataan yang paling tepat tentang keadaan itu!',options:['Pencatatan transaksi menjadi wajib dalam keadaan apa pun sehingga transaksi tunai yang kecil pun berdosa apabila tidak dicatat oleh pedagang','Pencatatan transaksi yang tidak tunai dianjurkan untuk menjaga hak kedua pihak sehingga catatan itu menjadi alat pembuktian apabila terjadi perselisihan tentang jumlah dan waktu pembayaran','Menjelaskan cacat barang kepada pembeli merupakan bagian dari kejujuran dalam perdagangan sehingga keberkahan transaksi itu terjaga dan pembeli tidak memperoleh barang yang tidak sesuai dengan harganya','Menepati timbangan tidak termasuk bagian dari ibadah karena timbangan merupakan urusan duniawi sehingga pedagang tidak memperoleh nilai ibadah dari ketepatannya'],answers:[1,2],explanation:'Dua pernyataan yang tepat adalah pernyataan pertama dan kedua. Menjelaskan cacat barang merupakan bagian dari kejujuran yang menjaga keberkahan transaksi, dan pencatatan transaksi yang tidak tunai menjaga hak kedua pihak sebagai alat pembuktian. Pernyataan ketiga keliru karena menepati timbangan termasuk perintah agama sehingga pelakunya memperoleh nilai ibadah dari ketaatannya. Pernyataan keempat keliru karena pencatatan dianjurkan untuk menjaga hak dan bukan merupakan kewajiban yang menjadikan pedagang berdosa apabila tidak mencatat transaksi tunai yang kecil.'},
{level:'HOTS',indicator:'Menentukan dua ketentuan yang tepat tentang rukun dan syarat sah jual beli',text:'Seorang pedagang menjual barang kepada pembeli yang masih berusia sepuluh tahun dengan harga yang lebih tinggi dari harga pasar, sementara barang yang dijual ternyata milik pihak lain yang dititipkan kepadanya untuk dijual. Pilihlah dua ketentuan yang paling tepat tentang rukun dan syarat jual beli!',options:['Rukun jual beli mencakup pihak yang berakad, barang yang diperjualbelikan, dan ijab kabul sehingga ketiganya perlu ada dalam setiap transaksi','Anak yang belum balig tetap sah melakukan akad jual beli tanpa pertimbangan apa pun sehingga umur pembeli tidak termasuk syarat yang perlu diperhatikan','Barang yang diperjualbelikan harus milik penjual atau penjual memiliki izin untuk menjualnya sehingga penjualan barang titipan tanpa izin pemiliknya tidak memenuhi syarat','Harga yang lebih tinggi dari harga pasar menjadikan jual beli itu batal sehingga setiap transaksi wajib menggunakan harga yang ditetapkan oleh pemerintah'],answers:[0,2],explanation:'Dua ketentuan yang tepat adalah ketentuan pertama dan kedua. Rukun jual beli mencakup tiga unsur dan barang yang dijual harus milik penjual atau dijual dengan izin pemiliknya. Ketentuan ketiga keliru karena transaksi anak yang belum balig memerlukan pertimbangan kemampuan membedakan baik dan buruk serta izin walinya untuk transaksi yang bernilai besar. Ketentuan keempat keliru karena harga yang tinggi tidak membatalkan akad selama terdapat kerelaan dan tidak ada penipuan, walaupun menipu pembeli dengan harga yang tidak wajar termasuk perbuatan yang dilarang.'},
{level:'HOTS',indicator:'Menerapkan dua ketentuan khiyar pada transaksi yang dilakukan melalui jaringan internet',text:'Sebuah toko daring menjual jaket dengan foto yang berbeda dari barang yang dikirim sehingga pembeli menerima jaket dengan bahan yang lebih tipis dan warna yang tidak sama. Pilihlah dua ketentuan yang paling tepat tentang penerapan khiyar pada transaksi itu!',options:['Pembeli tidak memiliki hak pengembalian karena ia telah menyetujui pembelian dengan menekan tombol pesan sehingga seluruh risiko menjadi tanggungannya','Pembeli berhak mengembalikan barang karena terdapat perbedaan antara keterangan pada iklan dan barang yang diterima sehingga perbedaan itu termasuk cacat yang tidak diketahuinya ketika akad','Khiyar aib berlaku pada transaksi daring sebagaimana berlaku pada transaksi langsung karena yang menentukan hak pengembalian adalah ketidaksesuaian barang dengan keterangan ketika akad','Penjual dapat menolak pengembalian dengan alasan bahwa foto pada iklan hanya bersifat hiasan sehingga keterangan barang tidak mengikat dalam transaksi daring'],answers:[1,2],explanation:'Dua ketentuan yang tepat adalah ketentuan pertama dan kedua. Perbedaan antara keterangan pada iklan dan barang yang diterima termasuk cacat yang tidak diketahui pembeli ketika akad sehingga ia berhak mengembalikan barang, dan khiyar aib berlaku pada transaksi daring sebagaimana pada transaksi langsung. Ketentuan ketiga keliru karena persetujuan membeli tidak menghapus hak pembeli atas barang yang tidak sesuai keterangan. Ketentuan keempat keliru karena keterangan barang pada iklan merupakan bagian dari kesepakatan sehingga penjual terikat oleh keterangan yang disampaikannya.'},
{level:'HOTS',indicator:'Menganalisis dua pernyataan yang tepat tentang prinsip dasar muamalah dan kedudukannya',text:'Sebuah diskusi di kelas membahas kedudukan muamalah dalam keseluruhan ajaran Islam setelah siswa membaca ayat tentang larangan memakan harta dengan cara yang batil. Pilihlah dua pernyataan yang paling tepat tentang prinsip dasar muamalah!',options:['Hukum asal dalam muamalah adalah boleh sampai terdapat keterangan yang melarangnya sehingga bentuk transaksi baru dapat diterima selama tidak mengandung larangan','Muamalah berlandaskan kerelaan kedua pihak dan tolong-menolong sehingga transaksi yang mengandung paksaan atau penipuan tidak memenuhi prinsip dasarnya','Muamalah merupakan urusan dunia yang terpisah dari ajaran agama sehingga ketentuan halal dan haram tidak berlaku pada kegiatan perdagangan','Hukum asal dalam muamalah adalah terlarang sehingga setiap bentuk transaksi memerlukan keterangan yang membolehkannya secara khusus sebelum dilaksanakan'],answers:[0,1],explanation:'Dua pernyataan yang tepat adalah pernyataan pertama dan kedua. Hukum asal muamalah adalah boleh sampai terdapat keterangan yang melarang, dan landasannya adalah kerelaan kedua pihak serta tolong-menolong. Pernyataan ketiga keliru karena membalik kaidah yang berlaku yaitu hukum asal muamalah adalah kebolehan dan bukan larangan. Pernyataan keempat keliru karena muamalah termasuk bagian ajaran Islam sehingga ketentuan halal dan haram berlaku pada seluruh kegiatan perdagangan.'},
{level:'HOTS',indicator:'Menganalisis dua ketentuan yang tepat tentang macam khiyar dan hikmahnya',text:'Seorang pembeli menyesal setelah membeli sebuah telepon genggam karena ia merasa tergesa-gesa dan belum membandingkan harganya dengan toko lain. Pilihlah dua ketentuan yang paling tepat tentang khiyar dan hikmah disyariatkannya!',options:['Khiyar majlis memberikan hak kepada kedua pihak untuk membatalkan atau melanjutkan transaksi selama keduanya belum berpisah dari tempat akad','Khiyar aib memberikan hak kepada pembeli untuk menuntut pengembalian barang walaupun cacat itu telah diketahuinya sebelum akad dan ia tetap menerimanya','Khiyar hanya berlaku bagi pembeli sehingga penjual tidak memiliki hak untuk membatalkan transaksi walaupun pembeli belum membayar dan belum berpisah darinya','Hikmah disyariatkannya khiyar adalah menjaga kedua pihak dari penyesalan dan kerugian sehingga transaksi dilakukan dengan pertimbangan yang matang dan bukan karena tergesa-gesa'],answers:[0,3],explanation:'Dua ketentuan yang tepat adalah ketentuan pertama dan kedua. Khiyar majlis berlaku selama kedua pihak belum berpisah dari tempat akad, dan hikmah khiyar adalah menjaga keduanya dari penyesalan dan kerugian. Ketentuan ketiga keliru karena khiyar aib berlaku untuk cacat yang tidak diketahui ketika akad sehingga cacat yang telah diketahui dan diterima tidak menimbulkan hak pengembalian. Ketentuan keempat keliru karena khiyar merupakan hak kedua pihak dan bukan hak pembeli saja.'},
{level:'HOTS',indicator:'Mengevaluasi dua ketentuan yang tepat tentang ijarah, wakalah, dan rahn',text:'Sebuah usaha percetakan menyewakan mesin kepada pihak lain, menerima pesanan percetakan sebagai wakil dari sebuah sekolah, dan memberikan pinjaman dengan jaminan sebuah kendaraan. Pilihlah dua ketentuan yang paling tepat tentang tiga akad itu!',options:['Wakalah sah apabila pekerjaan yang diwakilkan merupakan pekerjaan yang boleh diwakilkan dan pihak yang mewakilkan memiliki hak atas pekerjaan itu sehingga pesanan percetakan atas nama sekolah dapat dilaksanakan oleh percetakan sebagai wakil','Rahn menjadikan barang jaminan milik pemberi pinjaman secara otomatis apabila peminjam tidak mampu melunasi utangnya pada waktu yang telah disepakati','Menyewakan ruangan untuk kegiatan yang mengandung kemaksiatan tetap sah karena pemilik ruangan tidak ikut serta dalam kegiatan itu sehingga tanggung jawabnya hanya pada penyediaan tempat','Ijarah sah apabila manfaat yang disewakan jelas, jangka waktunya tertentu, dan upahnya disepakati sehingga penyewaan mesin itu memenuhi syarat selama ketiganya ditetapkan dalam akad'],answers:[0,3],explanation:'Dua ketentuan yang tepat adalah ketentuan pertama dan kedua. Ijarah memerlukan kejelasan manfaat, jangka waktu, dan upah, dan wakalah sah untuk pekerjaan yang boleh diwakilkan oleh pihak yang berhak atasnya. Ketentuan ketiga keliru karena barang jaminan dalam rahn bukan menjadi milik pemberi pinjaman melainkan dijual untuk melunasi utang dan kelebihannya dikembalikan kepada pemiliknya. Ketentuan keempat keliru karena menyewakan barang untuk kemaksiatan tidak diperbolehkan walaupun pemiliknya tidak ikut serta, karena sewa itu merupakan sarana bagi perbuatan yang dilarang.'},
{level:'HOTS',indicator:'Mengevaluasi dua ketentuan yang tepat tentang jual beli yang terlarang karena barangnya',text:'Sebuah kios menjual empat jenis barang: minuman yang memabukkan, minyak wangi yang mengandung alkohol untuk pemakaian luar, bangkai hewan yang telah dikeringkan sebagai hiasan, dan pakaian yang diperoleh dari pencurian. Pilihlah dua ketentuan yang paling tepat!',options:['Seluruh barang yang mengandung alkohol tidak boleh diperjualbelikan tanpa pengecualian sehingga minyak wangi untuk pemakaian luar juga termasuk yang dilarang','Jual beli barang yang diperoleh dari pencurian tidak sah karena barang itu bukan milik penjual sehingga pemilik yang sebenarnya berhak mengambilnya kembali','Bangkai hewan yang telah dikeringkan menjadi suci sehingga boleh dijual sebagai hiasan karena proses pengeringan menghilangkan najisnya','Jual beli barang yang zatnya diharamkan tidak sah sehingga penjual dan pembelinya sama-sama memperoleh dosa dari transaksi itu'],answers:[1,3],explanation:'Dua ketentuan yang tepat adalah ketentuan pertama dan kedua. Barang yang zatnya diharamkan tidak sah diperjualbelikan dan barang hasil pencurian bukan milik penjual sehingga pemiliknya berhak mengambilnya kembali. Ketentuan ketiga keliru karena penggunaan alkohol untuk keperluan luar yang tidak dikonsumsi memiliki ketentuan tersendiri sehingga pengharaman yang mutlak itu tidak tepat. Ketentuan keempat keliru karena bangkai tidak menjadi suci dengan pengeringan sehingga memperjualbelikannya tetap tidak diperbolehkan.'},
{level:'HOTS',indicator:'Menganalisis dua ketentuan yang tepat tentang penipuan harga dan penimbunan barang',text:'Menjelang bulan Ramadan, seorang pedagang menimbun minyak goreng agar harganya naik, sementara pedagang lain menyuruh temannya menawarkan harga tinggi pada lelang agar pembeli lain ikut menaikkan penawarannya. Pilihlah dua ketentuan yang paling tepat!',options:['Penawaran palsu pada lelang diperbolehkan selama pembeli terakhir merasa rela dengan harga yang dibayarnya sehingga kerelaan pembeli menghapus unsur penipuan','Menimbun barang milik sendiri diperbolehkan dalam keadaan apa pun karena pedagang memiliki hak penuh atas barangnya sehingga masyarakat tidak berhak menuntut apa pun','Menimbun barang kebutuhan ketika masyarakat memerlukannya termasuk perbuatan yang diharamkan karena menimbulkan kesulitan dan kenaikan harga yang merugikan banyak pihak','Penawaran palsu pada lelang termasuk najasy yang diharamkan karena menipu pembeli dengan menaikkan harga melalui penawaran yang tidak dimaksudkan untuk membeli'],answers:[2,3],explanation:'Dua ketentuan yang tepat adalah ketentuan pertama dan kedua. Penimbunan barang kebutuhan ketika masyarakat memerlukannya diharamkan karena menimbulkan kesulitan, dan penawaran palsu pada lelang termasuk najasy yang diharamkan karena mengandung penipuan. Ketentuan ketiga keliru karena hak milik tidak menghapus larangan menimbulkan kesulitan bagi masyarakat sehingga penimbunan tetap dilarang pada keadaan yang merugikan. Ketentuan keempat keliru karena kerelaan pembeli yang didasarkan pada keterangan yang palsu bukan merupakan kerelaan yang sah.'},
{level:'HOTS',indicator:'Menganalisis dua ketentuan yang tepat tentang akad mudharabah dan musyarakah',text:'Sebuah koperasi madrasah memperoleh modal dari seorang donatur yang tidak ikut mengelola usaha, sementara tiga orang siswa mengumpulkan modal bersama dan seluruhnya ikut mengelola usaha penjualan alat tulis. Pilihlah dua ketentuan yang paling tepat!',options:['Kerja sama antara donatur dan koperasi termasuk mudharabah karena modal berasal dari satu pihak dan pengelolaan dilakukan oleh pihak lain dengan pembagian keuntungan sesuai kesepakatan','Musyarakah mensyaratkan bahwa hanya satu pihak yang menyetorkan modal sedangkan pihak lain menyumbangkan tenaga saja sehingga usaha tiga siswa itu bukan termasuk musyarakah','Kerja sama tiga siswa termasuk musyarakah karena seluruh pihak menyetorkan modal dan ikut mengelola usaha sehingga keuntungan dibagi sesuai kesepakatan dan kerugian ditanggung menurut porsi modal','Dalam mudharabah kerugian harta ditanggung oleh pengelola usaha sehingga donatur tidak menanggung kerugian apa pun walaupun kerugian itu bukan karena kelalaian pengelola'],answers:[0,2],explanation:'Dua ketentuan yang tepat adalah ketentuan pertama dan kedua. Mudharabah merupakan kerja sama antara pemilik modal dan pengelola dengan pembagian keuntungan sesuai kesepakatan, dan musyarakah merupakan kerja sama yang seluruh pesertanya menyetorkan modal dan ikut mengelola. Ketentuan ketiga keliru karena kerugian harta dalam mudharabah ditanggung oleh pemilik modal selama kerugian itu bukan akibat kelalaian pengelola, sedangkan pengelola menanggung kerugian tenaganya. Ketentuan keempat keliru karena musyarakah justru mensyaratkan seluruh pihak menyetorkan modal.'},
{level:'HOTS',indicator:'Menentukan dua ketentuan yang tepat tentang akad salam dan jual beli kredit',text:'Seorang petani memerlukan modal untuk menanam padi dan menawarkan hasil panennya kepada pedagang dengan penyerahan tertunda, sementara pembeli lain ingin membeli sepeda motor dengan pembayaran yang dicicil. Pilihlah dua ketentuan yang paling tepat!',options:['Akad salam diperbolehkan dengan pembayaran di muka untuk barang yang jelas sifat, jenis, takaran, dan waktu penyerahannya sehingga ketidakadaan barang ketika akad tidak membatalkannya','Jual beli kredit dengan harga yang lebih tinggi dari harga tunai diperbolehkan selama harga itu disepakati pada awal akad dan tidak bertambah karena keterlambatan pembayaran','Akad salam tidak sah dalam keadaan apa pun karena penjual belum memiliki barang ketika akad sehingga termasuk menjual barang yang belum dimiliki','Jual beli kredit menjadi tidak sah karena harga kredit lebih tinggi dari harga tunai sehingga setiap kenaikan harga dalam transaksi yang tidak tunai termasuk riba'],answers:[0,1],explanation:'Dua ketentuan yang tepat adalah ketentuan pertama dan kedua. Akad salam diperbolehkan apabila sifat, jenis, takaran, dan waktu penyerahan barang telah jelas, dan jual beli kredit dengan harga yang lebih tinggi sah selama disepakati pada awal akad dan tidak bertambah karena keterlambatan. Ketentuan ketiga keliru karena akad salam justru merupakan pengecualian yang ditetapkan oleh keterangan agama untuk memudahkan pihak yang memerlukan modal. Ketentuan keempat keliru karena perbedaan harga tunai dan harga kredit yang disepakati di awal bukan merupakan riba selama tidak terdapat tambahan yang timbul dari penundaan pembayaran.'}
],
'bs':[
{level:'HOTS',indicator:'Menilai pernyataan tentang penanggung kerugian dalam akad mudharabah',text:'Pernyataan: Kerugian harta dalam akad mudharabah ditanggung oleh pemilik modal selama kerugian itu bukan disebabkan oleh kelalaian atau pelanggaran ketentuan oleh pengelola usaha. Penilaian yang tepat atas pernyataan tersebut adalah ...',answer:true,explanation:'Pernyataan itu benar. Pembagian dalam mudharabah menempatkan keuntungan sesuai kesepakatan dan kerugian harta pada pemilik modal karena modal merupakan miliknya, sedangkan pengelola menanggung kerugian tenaga dan waktu yang telah dicurahkan. Keadaan itu berubah apabila kerugian timbul karena kelalaian pengelola sehingga ia bertanggung jawab atas kerugian yang disebabkan oleh kelalaiannya.'},
{level:'HOTS',indicator:'Menilai pernyataan tentang anjuran mencatat transaksi yang tidak tunai',text:'Seorang pedagang menyatakan bahwa mencatat transaksi yang tidak tunai dianjurkan untuk menjaga hak kedua pihak sehingga catatan itu menjadi alat pembuktian apabila terjadi perselisihan. Penilaian yang tepat atas pernyataan tersebut adalah ...',answer:true,explanation:'Pernyataan itu benar. Pencatatan transaksi yang tidak tunai dianjurkan karena menjaga hak kedua pihak dan mencegah perselisihan tentang jumlah, waktu, dan syarat pembayaran. Anjuran ini menjadi dasar pembukuan dalam usaha sehingga pedagang yang mencatat transaksinya telah melaksanakan bagian dari adab bermuamalah dan memperoleh kepastian dalam pengelolaan usahanya.'},
{level:'HOTS',indicator:'Menilai pernyataan tentang jangka waktu khiyar syarat',text:'Cermati pernyataan berikut: Khiyar syarat dapat ditetapkan untuk jangka waktu yang tidak terbatas sehingga pembeli boleh membatalkan transaksi bertahun-tahun sesudah akad berlangsung. Penilaian yang tepat atas pernyataan tersebut adalah ...',answer:false,explanation:'Pernyataan itu salah. Khiyar syarat ditetapkan untuk jangka waktu yang tertentu dan diketahui oleh kedua pihak sehingga ketidakjelasan jangka waktu menjadikan akad mengandung ketidakpastian yang dapat merugikan salah satu pihak. Ketentuan ini menjaga keseimbangan antara hak pembeli untuk mempertimbangkan dan kepastian bagi penjual atas barang yang telah dijualnya.'},
{level:'HOTS',indicator:'Menilai pernyataan tentang menyewakan tempat untuk kegiatan yang mengandung kemaksiatan',text:'Pernyataan: Menyewakan ruangan untuk kegiatan yang mengandung kemaksiatan diperbolehkan selama pemilik ruangan tidak ikut serta dalam kegiatan itu. Penilaian yang tepat atas pernyataan tersebut adalah ...',answer:false,explanation:'Pernyataan itu salah. Menyewakan barang atau tempat untuk kegiatan yang mengandung kemaksiatan tidak diperbolehkan karena sewa itu merupakan sarana bagi terlaksananya perbuatan yang dilarang, sehingga pemilik tempat ikut menanggung dosa walaupun tidak hadir dalam kegiatan itu. Ketentuan ini menunjukkan bahwa muamalah dinilai dari tujuan penggunaannya dan bukan hanya dari bentuk akadnya.'},
{level:'HOTS',indicator:'Menilai pernyataan tentang sebab diharamkannya najasy',text:'Seorang siswa menyatakan bahwa najasy diharamkan karena penawaran palsu itu menipu pembeli dengan menaikkan harga melalui pihak yang tidak bermaksud membeli barang tersebut. Penilaian yang tepat atas pernyataan tersebut adalah ...',answer:true,explanation:'Pernyataan itu benar. Najasy merupakan penawaran palsu yang dilakukan oleh pihak yang bekerja sama dengan penjual untuk menimbulkan kesan bahwa barang itu banyak peminatnya sehingga pembeli menaikkan penawarannya. Keharamannya terletak pada unsur penipuan yang merugikan pembeli, karena pembeli menetapkan harga berdasarkan keterangan yang tidak sesuai dengan keadaan yang sebenarnya.'},
{level:'HOTS',indicator:'Menilai pernyataan tentang keabsahan jual beli dengan uang elektronik',text:'Seorang siswa menyatakan bahwa jual beli dengan uang elektronik sah selama nilai yang tersimpan dalam saldonya jelas, barang yang dibeli jelas, dan tidak terdapat unsur riba dalam pengisian atau penggunaannya. Penilaian yang tepat atas pernyataan tersebut adalah ...',answer:true,explanation:'Pernyataan itu benar. Uang elektronik berkedudukan sebagai alat pembayaran sehingga keabsahan transaksi bergantung pada kejelasan nilai, kejelasan barang, dan tidak terdapat unsur yang dilarang dalam pengisian serta penggunaannya. Ketentuan ini menunjukkan bahwa perkembangan alat pembayaran tidak mengubah prinsip muamalah selama syarat dan rukun transaksinya terpenuhi.'},
{level:'HOTS',indicator:'Menilai pernyataan tentang kerelaan pihak dalam transaksi yang mengandung gharar',text:'Cermati pernyataan berikut: Jual beli yang mengandung ketidakjelasan tentang barang atau hasil dapat menjadi sah karena kerelaan kedua pihak menghapus unsur ketidakjelasan itu. Penilaian yang tepat atas pernyataan tersebut adalah ...',answer:false,explanation:'Pernyataan itu salah. Ketidakjelasan tentang barang atau hasil merupakan sebab terlarangnya transaksi sehingga kerelaan kedua pihak tidak dapat menghapusnya, karena kerelaan yang sah memerlukan kejelasan objek yang direlakan. Ketentuan ini melindungi kedua pihak dari perselisihan yang timbul sesudah transaksi dan dari kerugian yang tidak dapat diperhitungkan ketika akad berlangsung.'},
{level:'HOTS',indicator:'Menilai pernyataan tentang menimbun barang kebutuhan masyarakat',text:'Pernyataan: Menimbun barang kebutuhan pokok ketika masyarakat sangat membutuhkannya diperbolehkan karena penimbun memiliki hak penuh atas barang miliknya. Penilaian yang tepat atas pernyataan tersebut adalah ...',answer:false,explanation:'Pernyataan itu salah. Menimbun barang kebutuhan pokok pada saat masyarakat membutuhkannya diharamkan karena menimbulkan kesulitan dan kenaikan harga yang merugikan banyak pihak sehingga hak milik tidak dapat digunakan sebagai alasan. Ketentuan ini menunjukkan bahwa muamalah tidak hanya memperhatikan hak individu melainkan juga kepentingan masyarakat yang lebih luas.'},
{level:'HOTS',indicator:'Menilai pernyataan tentang berlakunya khiyar majlis',text:'Pernyataan: Khiyar majlis memberikan hak kepada kedua pihak untuk membatalkan atau melanjutkan transaksi selama keduanya belum berpisah dari tempat akad. Penilaian yang tepat atas pernyataan tersebut adalah ...',answer:true,explanation:'Pernyataan itu benar. Khiyar majlis berlaku selama kedua pihak masih berada dalam satu majelis akad sehingga masing-masing berhak memilih untuk melanjutkan atau membatalkan. Ketentuan ini memberikan kesempatan bagi kedua pihak untuk mempertimbangkan kembali transaksinya sebelum berpisah dan mencegah timbulnya penyesalan sesudah akad selesai.'},
{level:'HOTS',indicator:'Menilai pernyataan tentang menjual barang yang belum dimiliki',text:'Cermati pernyataan berikut: Menjual barang yang belum dimiliki sah dilakukan karena penjual dapat membeli barang itu sesudah menerima pembayaran dari pembeli. Penilaian yang tepat atas pernyataan tersebut adalah ...',answer:false,explanation:'Pernyataan itu salah. Menjual barang yang belum dimiliki dan belum berada dalam tanggungannya tidak diperbolehkan karena penjual tidak dapat menjamin penyerahan barang itu kepada pembeli, dan keadaan itu mengandung unsur ketidakpastian yang merugikan pembeli. Pengecualian berlaku pada akad salam yang barangnya jelas sifat, jenis, takaran, dan waktu penyerahannya dengan pembayaran di muka.'}
],
'singkat':[
{level:'HOTS',indicator:'Menyebut istilah untuk hak memilih dalam transaksi jual beli',text:'Sebutan bagi hak yang dimiliki oleh pihak yang bertransaksi untuk memilih antara melanjutkan atau membatalkan akad jual beli, yang hikmahnya adalah menjaga kedua pihak dari penyesalan dan kerugian sesudah transaksi berlangsung, adalah ....',answer:'khiyar',accepted:['khiyar','hak khiyar','berkhiyar','khiyar jual beli'],explanation:'Sebutan itu adalah khiyar. Kedudukannya sebagai hak bagi kedua pihak menjadikan transaksi tidak mengikat secara mutlak pada saat akad sehingga terdapat kesempatan untuk mempertimbangkan kembali. Pembedaannya dari pembatalan sepihak yang sewenang-wenang penting karena khiyar berlaku dalam keadaan dan jangka waktu yang telah ditentukan sehingga hak itu tidak digunakan untuk merugikan pihak lain.'},
{level:'HOTS',indicator:'Menyebut istilah untuk ketidakjelasan yang menjadikan transaksi terlarang',text:'Sebutan bagi ketidakjelasan tentang barang, harga, atau hasil suatu transaksi sehingga menimbulkan risiko kerugian yang tidak dapat diperhitungkan oleh kedua pihak dan menjadikan transaksi itu terlarang walaupun keduanya menyatakan rela, adalah ....',answer:'gharar',accepted:['gharar','ketidakjelasan','unsur gharar','transaksi gharar'],explanation:'Sebutan itu adalah gharar. Kedudukannya sebagai sebab terlarangnya transaksi menunjukkan bahwa kerelaan kedua pihak tidak dapat menghapus ketidakjelasan karena kerelaan yang sah memerlukan kejelasan objek yang direlakan. Pembedaannya dari penipuan penting karena gharar berkaitan dengan keadaan objek yang tidak jelas sedangkan penipuan berkaitan dengan penyampaian keterangan yang tidak sesuai dengan keadaan yang sebenarnya.'},
{level:'HOTS',indicator:'Menyebut istilah untuk akad pemesanan barang dengan pembayaran di muka',text:'Sebutan bagi akad pemesanan barang dengan pembayaran di muka sedangkan barangnya diserahkan pada waktu yang telah ditentukan, yang diperbolehkan sebagai pengecualian dari larangan menjual barang yang belum dimiliki selama jenis, sifat, takaran, dan waktu penyerahannya jelas, adalah akad ....',answer:'salam',accepted:['salam','akad salam','jual beli salam','pesan salam'],explanation:'Sebutan itu adalah akad salam. Kedudukannya sebagai pengecualian menunjukkan kemudahan bagi pihak yang memerlukan modal untuk usahanya seperti petani yang memerlukan biaya penanaman sebelum panen. Pembedaannya dari jual beli biasa penting karena dalam akad salam pembayaran dilakukan di muka sedangkan barang diserahkan kemudian, sehingga kejelasan sifat dan waktu penyerahan menjadi syarat yang menentukan keabsahannya.'},
{level:'HOTS',indicator:'Menyebut istilah untuk penimbunan barang kebutuhan yang merugikan masyarakat',text:'Sebutan bagi perbuatan menimbun barang kebutuhan masyarakat pada waktu mereka sangat memerlukannya dengan tujuan menunggu kenaikan harga sehingga masyarakat mengalami kesulitan dan harga menjadi tidak wajar, adalah ....',answer:'ihtikar',accepted:['ihtikar','penimbunan','monopoli penimbunan','menimbun barang'],explanation:'Sebutan itu adalah ihtikar. Kedudukannya sebagai perbuatan yang diharamkan berkaitan dengan kesulitan yang ditimbulkannya bagi masyarakat sehingga hak milik atas barang tidak dapat digunakan sebagai alasan untuk membenarkannya. Pembedaannya dari penyimpanan barang untuk keperluan sendiri penting karena ihtikar dilakukan dengan tujuan memperoleh keuntungan dari kesulitan masyarakat dan pada barang yang dibutuhkan oleh banyak pihak.'},
{level:'HOTS',indicator:'Menyebut istilah untuk hubungan antarmanusia dalam urusan harta dan jasa',text:'Sebutan bagi hubungan antarmanusia dalam urusan harta, jasa, dan pertukaran manfaat yang diatur oleh ketentuan agama sehingga kehalalan dan keharaman berlaku pada seluruh bentuk transaksinya, adalah ....',answer:'muamalah',accepted:['muamalah','mu amalah','fiqih muamalah','hubungan muamalah'],explanation:'Sebutan itu adalah muamalah. Kedudukannya sebagai bagian dari ajaran Islam menjadikan kegiatan ekonomi tidak terlepas dari ketentuan agama sehingga prinsip kerelaan, kejujuran, dan keadilan berlaku padanya. Pembedaannya dari ibadah mahdah penting karena hukum asal muamalah adalah boleh sampai terdapat keterangan yang melarang, sedangkan hukum asal ibadah adalah terlarang sampai terdapat keterangan yang memerintahkannya.'},
{level:'HOTS',indicator:'Menyebut istilah untuk penawaran palsu yang menaikkan harga barang',text:'Sebutan bagi penawaran palsu yang dilakukan oleh pihak yang tidak bermaksud membeli barang dengan tujuan menaikkan harga sehingga pembeli yang sebenarnya tertipu oleh kesan banyaknya peminat, adalah ....',answer:'najasy',accepted:['najasy','najsy','penawaran najasy','penawaran palsu'],explanation:'Sebutan itu adalah najasy. Kedudukannya sebagai perbuatan yang diharamkan berkaitan dengan unsur penipuan yang merugikan pembeli sehingga harga yang dibayarnya tidak mencerminkan nilai barang yang sebenarnya. Pembedaannya dari persaingan harga yang wajar penting karena dalam persaingan yang wajar setiap penawar benar-benar bermaksud membeli barang sedangkan dalam najasy penawaran itu hanya dimaksudkan untuk mempengaruhi pihak lain.'},
{level:'HOTS',indicator:'Menyebut istilah untuk kerja sama yang seluruh pesertanya menyetorkan modal',text:'Sebutan bagi kerja sama usaha yang seluruh pesertanya menyetorkan modal dan ikut mengelola usaha sehingga keuntungan dibagi sesuai kesepakatan dan kerugian ditanggung menurut porsi modal masing-masing peserta, adalah ....',answer:'musyarakah',accepted:['musyarakah','akad musyarakah','syirkah','musyarakah usaha'],explanation:'Sebutan itu adalah musyarakah. Kedudukannya menjadikan seluruh peserta memiliki tanggung jawab atas modal dan pengelolaan sehingga kerugian harta ditanggung menurut porsi modal dan bukan dibagi rata. Pembedaannya dari mudharabah penting karena dalam musyarakah setiap peserta merupakan pemilik modal sekaligus pengelola, sedangkan dalam mudharabah kedudukan pemilik modal dan pengelola berada pada pihak yang berbeda.'},
{level:'HOTS',indicator:'Menyebut istilah untuk kerja sama antara pemilik modal dan pengelola usaha',text:'Sebutan bagi kerja sama usaha antara pemilik modal yang menyerahkan seluruh modalnya dan pengelola yang menjalankan usaha, dengan pembagian keuntungan sesuai kesepakatan dan kerugian harta ditanggung oleh pemilik modal selama bukan karena kelalaian pengelola, adalah ....',answer:'mudharabah',accepted:['mudharabah','qirad','akad mudharabah','mudharabah usaha'],explanation:'Sebutan itu adalah mudharabah yang juga disebut qirad. Kedudukannya memungkinkan pihak yang memiliki modal namun tidak mampu mengelola usaha untuk memperoleh keuntungan melalui pihak yang mampu mengelola namun tidak memiliki modal. Pembedaannya dari musyarakah penting karena dalam mudharabah hanya satu pihak yang menyetorkan modal sedangkan dalam musyarakah seluruh pihak menyetorkan modal dan ikut mengelola usaha.'},
{level:'HOTS',indicator:'Menyebut istilah untuk khiyar yang ditetapkan dengan perjanjian dalam akad',text:'Sebutan bagi hak memilih yang ditetapkan melalui perjanjian dalam akad jual beli untuk jangka waktu yang tertentu dan diketahui oleh kedua pihak, sehingga pembeli dapat mempertimbangkan barang itu terlebih dahulu sebelum transaksinya menjadi mengikat, adalah khiyar ....',answer:'syarat',accepted:['syarat','khiyar syarat','khiyar dengan syarat','syarat dalam akad'],explanation:'Sebutan itu adalah khiyar syarat. Kedudukannya timbul dari kesepakatan kedua pihak sehingga jangka waktunya perlu tertentu dan diketahui agar tidak menimbulkan ketidakpastian. Pembedaannya dari khiyar majlis penting karena khiyar majlis berlaku dengan sendirinya selama kedua pihak belum berpisah dari tempat akad sedangkan khiyar syarat memerlukan perjanjian yang dinyatakan ketika akad berlangsung.'},
{level:'HOTS',indicator:'Menyebut istilah untuk akad sewa manfaat atas barang atau jasa',text:'Sebutan bagi akad pemindahan hak atas manfaat suatu barang atau jasa untuk jangka waktu yang tertentu dengan imbalan upah yang disepakati, sedangkan kepemilikan barangnya tetap berada pada pemiliknya, adalah ....',answer:'ijarah',accepted:['ijarah','akad ijarah','sewa ijarah','ijarah manfaat'],explanation:'Sebutan itu adalah ijarah. Kedudukannya sebagai akad atas manfaat dan bukan atas barang menjadikan kepemilikan barang tetap berada pada pemiliknya sehingga penyewa hanya berhak menggunakan manfaat itu sesuai kesepakatan. Pembedaannya dari jual beli penting karena dalam jual beli kepemilikan barang berpindah kepada pembeli sedangkan dalam ijarah yang berpindah hanyalah hak memanfaatkan untuk jangka waktu yang tertentu.'}
],
'essay':[
{level:'HOTS',indicator:'Mengevaluasi empat transaksi jual beli lalu menyimpulkan prinsip keabsahan transaksi',text:'Empat transaksi terjadi di pasar sebuah kota pada hari Jumat: seorang pedagang menjual dagangannya ketika azan salat Jumat telah berkumandang padahal ia wajib menghadirinya, seorang pemuda menjual telepon genggam milik saudaranya tanpa izin, seorang pembeli dipaksa membeli barang dengan harga tinggi karena barangnya telah dirusak oleh penjual, dan seorang pedagang menjual minuman yang memabukkan kepada pembelinya. Evaluasilah keempat transaksi itu dengan menentukan sah atau tidaknya beserta alasannya, lalu simpulkanlah dua prinsip yang menentukan keabsahan suatu jual beli!',key:'Evaluasi transaksi pertama: jual beli yang dilakukan ketika azan salat Jumat telah berkumandang oleh pihak yang wajib menghadiri salat itu berkedudukan terlarang karena ia meninggalkan kewajiban untuk melaksanakan transaksi, sehingga transaksi itu perlu dihentikan dan kewajiban salat didahulukan; larangan ini berkaitan dengan perbuatan penjual dan bukan dengan keabsahan akad dari segi rukunnya, namun keberkahan transaksi itu hilang karena dilakukan dengan mengabaikan kewajiban. Evaluasi transaksi kedua: penjualan telepon genggam milik saudaranya tanpa izin tidak sah karena barang itu bukan miliknya dan ia tidak memiliki kewenangan untuk menjualnya, sehingga pemilik yang sebenarnya berhak mengambil kembali barang itu dari pembeli dan pembeli menuntut pengembalian uangnya kepada penjual. Evaluasi transaksi ketiga: jual beli yang dilakukan dengan paksaan tidak sah karena kerelaan kedua pihak merupakan landasan transaksi, dan paksaan yang disertai perusakan barang menjadikan kerelaan pembeli tidak ada sehingga ia berhak membatalkan transaksi dan menuntut ganti atas barangnya yang dirusak. Evaluasi transaksi keempat: penjualan minuman yang memabukkan tidak sah karena barang yang diperjualbelikan merupakan zat yang diharamkan sehingga transaksi itu tidak memenuhi syarat kehalalan barang dan kedua pihak memperoleh dosa dari transaksi tersebut. Dua prinsip yang menentukan keabsahan jual beli: pertama, prinsip kerelaan dan kewenangan, yaitu transaksi sah apabila kedua pihak merelakan tanpa paksaan dan pihak yang menjual memiliki barang itu atau memiliki izin dari pemiliknya sehingga tidak terdapat pengambilan hak pihak lain; kedua, prinsip kehalalan dan kejelasan objek, yaitu barang yang diperjualbelikan harus halal zatnya, jelas sifat dan jumlahnya, serta dapat diserahkan sehingga tidak terdapat unsur yang dilarang maupun ketidakjelasan yang menimbulkan kerugian sesudah akad.',rubric:['Mengevaluasi keempat transaksi dengan kesimpulan sah, tidak sah, atau terlarang untuk setiap transaksi disertai alasan yang tepat','Menjelaskan kedudukan kerelaan dan kewenangan menjual sebagai dasar penilaian transaksi kedua dan ketiga','Menjelaskan kedudukan kehalalan barang sebagai dasar penilaian transaksi keempat dan kedudukan kewajiban salat pada transaksi pertama','Menyimpulkan dua prinsip keabsahan jual beli yang mencakup keempat transaksi dan dapat diterapkan pada keadaan lain'],explanation:'Jawaban dinilai dari ketepatan evaluasi setiap transaksi dan keterpaduan dua prinsip yang disimpulkan. Siswa yang menyamaratakan keempat transaksi sebagai tidak sah tanpa membedakan sebab terlarang dan sebab tidak sah belum mencapai taraf evaluasi yang diminta.'},
{level:'HOTS',indicator:'Menganalisis tiga macam khiyar lalu menerapkannya pada transaksi daring',text:'Seorang pembeli menerima paket yang tidak sesuai dengan keterangan pada iklan karena bahan jaket yang dikirim lebih tipis dan warnanya berbeda, lalu penjual menolak pengembalian dengan alasan bahwa barang yang telah dibeli tidak dapat dikembalikan. Analisislah tiga macam khiyar beserta ketentuan dan jangka waktunya, terapkanlah ketiga macam khiyar itu pada transaksi daring tersebut, lalu susunlah tiga langkah yang dapat dilakukan pembeli untuk berhati-hati sebelum membeli melalui jaringan internet!',key:'Tiga macam khiyar: pertama, khiyar majlis yaitu hak kedua pihak untuk melanjutkan atau membatalkan transaksi selama keduanya belum berpisah dari tempat akad, sehingga jangka waktunya berakhir dengan berpisahnya kedua pihak dari majelis akad; kedua, khiyar syarat yaitu hak memilih yang ditetapkan melalui perjanjian dalam akad untuk jangka waktu yang tertentu dan diketahui oleh kedua pihak seperti satu hari atau tiga hari, sehingga pembeli dapat mempertimbangkan barang itu sebelum transaksi menjadi mengikat; ketiga, khiyar aib yaitu hak pembeli untuk mengembalikan barang apabila terdapat cacat pada barang yang tidak diketahuinya ketika akad, sehingga jangka waktunya berlaku sejak cacat itu diketahui dan tidak gugur walaupun kedua pihak telah berpisah dari majelis akad. Penerapan pada transaksi daring: khiyar majlis tidak dapat diterapkan secara langsung karena kedua pihak tidak berada dalam satu tempat sehingga batas berpisahnya majelis akad dipahami sebagai selesainya kesepakatan melalui sistem, namun hak pembeli tetap terjaga melalui khiyar yang lain; khiyar syarat dapat diterapkan apabila penjual mencantumkan ketentuan pengembalian dalam jangka waktu tertentu pada keterangan tokonya sehingga pembeli memperoleh kesempatan mempertimbangkan barang sesudah menerimanya; khiyar aib merupakan dasar yang paling tepat untuk transaksi itu karena perbedaan bahan dan warna antara keterangan pada iklan dan barang yang diterima termasuk cacat yang tidak diketahui pembeli ketika akad, sehingga alasan penjual bahwa barang yang telah dibeli tidak dapat dikembalikan tidak dapat diterima karena hak khiyar aib tidak dapat dihapus oleh pernyataan sepihak. Tiga langkah kehati-hatian pembeli: pertama, membaca keterangan barang secara lengkap termasuk bahan, ukuran, warna, dan ketentuan pengembalian yang ditetapkan penjual sehingga terdapat dasar khiyar syarat apabila keterangan itu diberikan; kedua, memeriksa reputasi penjual melalui ulasan pembeli sebelumnya dan memilih toko yang menyediakan jaminan pengembalian barang sehingga risiko perbedaan barang dapat dikurangi; ketiga, mendokumentasikan keadaan paket ketika dibuka berupa foto atau rekaman pembukaan paket serta menyimpan bukti pembayaran dan tangkapan layar keterangan iklan sehingga terdapat alat pembuktian apabila barang yang diterima tidak sesuai dengan keterangan ketika mengajukan pengembalian.',rubric:['Menganalisis tiga macam khiyar beserta ketentuan dan jangka waktu masing-masing secara tepat','Menerapkan khiyar majlis pada transaksi daring dengan menjelaskan keterbatasan penerapannya karena kedua pihak tidak berada dalam satu tempat','Menerapkan khiyar aib sebagai dasar pengembalian barang dan menolak alasan penjual dengan argumen yang tepat','Menyusun tiga langkah kehati-hatian yang konkret, berkaitan dengan khiyar, dan dapat dilaksanakan oleh pembeli sebelum bertransaksi'],explanation:'Jawaban dinilai dari ketepatan analisis tiga macam khiyar, ketajaman penerapannya pada transaksi daring, dan kepraktisan tiga langkah yang disusun. Siswa yang menyimpulkan pembeli tidak berhak mengembalikan barang belum memahami kedudukan khiyar aib.'},
{level:'HOTS',indicator:'Membandingkan lima akad kerja sama lalu mengevaluasi penerapannya pada koperasi madrasah',text:'Sebuah koperasi madrasah mengelola tiga bentuk kerja sama yaitu modal dari donatur yang usahanya dikelola siswa, modal bersama dari lima siswa yang seluruhnya ikut mengelola, serta penyewaan tenda kepada warga untuk kegiatan. Bandingkanlah akad mudharabah, musyarakah, ijarah, wakalah, dan salam dalam empat segi, tentukanlah akad yang tepat untuk ketiga kegiatan koperasi itu beserta alasannya, lalu evaluasilah rencana koperasi menyewakan tendanya untuk kegiatan yang mengandung kemaksiatan!',key:'Perbandingan lima akad dalam empat segi: pertama, dari segi objek akad, mudharabah dan musyarakah berobjek kerja sama usaha untuk memperoleh keuntungan, ijarah berobjek pemindahan hak atas manfaat barang atau jasa dengan upah, wakalah berobjek pelimpahan kewenangan untuk melaksanakan suatu pekerjaan atas nama pihak yang mewakilkan, dan salam berobjek pemesanan barang dengan pembayaran di muka dan penyerahan tertunda; kedua, dari segi penyetoran modal, mudharabah menempatkan seluruh modal pada satu pihak dan tenaga pada pihak lain, musyarakah menempatkan modal pada seluruh pihak yang juga ikut mengelola, ijarah tidak melibatkan penyetoran modal untuk usaha melainkan pembayaran upah atas manfaat, wakalah tidak memerlukan modal karena yang dilimpahkan adalah kewenangan, dan salam melibatkan pembayaran penuh di muka dari pihak pemesan; ketiga, dari segi pembagian keuntungan dan kerugian, mudharabah membagi keuntungan sesuai kesepakatan dan kerugian harta ditanggung pemilik modal selama bukan karena kelalaian pengelola, musyarakah membagi keuntungan sesuai kesepakatan dan kerugian menurut porsi modal, ijarah memberikan upah yang telah ditetapkan kepada penyedia manfaat tanpa pembagian keuntungan usaha, wakalah dapat disertai imbalan yang disepakati atau tanpa imbalan, dan salam memberikan keuntungan dari selisih harga pesan dengan harga pasar ketika barang diserahkan; keempat, dari segi kewenangan mengelola, mudharabah memberikan kewenangan penuh kepada pengelola dalam batas kesepakatan, musyarakah memberikan kewenangan kepada seluruh peserta sesuai kesepakatan, ijarah memberikan hak pakai kepada penyewa dalam batas yang disepakati, wakalah memberikan kewenangan kepada wakil hanya pada pekerjaan yang diwakilkan, dan salam tidak memberikan kewenangan pengelolaan kepada pemesan karena ia hanya menunggu penyerahan barang. Penentuan akad untuk tiga kegiatan koperasi: kegiatan pertama yaitu modal dari donatur yang dikelola siswa merupakan akad mudharabah karena modal berasal dari satu pihak dan pengelolaan dilakukan oleh pihak lain sehingga keuntungan dibagi sesuai kesepakatan dan kerugian harta ditanggung donatur selama bukan karena kelalaian pengelola; kegiatan kedua yaitu modal bersama dari lima siswa yang seluruhnya ikut mengelola merupakan akad musyarakah karena seluruh pihak menyetorkan modal dan ikut mengelola sehingga kerugian ditanggung menurut porsi modal masing-masing; kegiatan ketiga yaitu penyewaan tenda kepada warga merupakan akad ijarah karena yang dipindahkan adalah hak memanfaatkan tenda untuk jangka waktu tertentu dengan upah yang disepakati sedangkan kepemilikan tenda tetap pada koperasi. Evaluasi rencana penyewaan tenda untuk kegiatan yang mengandung kemaksiatan: rencana itu tidak diperbolehkan karena menyewakan barang untuk kegiatan yang mengandung kemaksiatan menjadikan akad itu sarana bagi perbuatan yang dilarang, sehingga pemilik barang ikut menanggung dosa walaupun tidak hadir dalam kegiatan itu; koperasi seharusnya menetapkan syarat penggunaan tenda dalam akad yaitu hanya untuk kegiatan yang tidak bertentangan dengan ketentuan agama dan menolak pemesanan yang tujuannya diketahui bertentangan dengan syarat itu, serta mencantumkan ketentuan pengembalian upah atau pembatalan akad apabila penyewa menggunakan tenda di luar tujuan yang disepakati.',rubric:['Membandingkan lima akad dalam empat segi yang berbeda yaitu objek akad, penyetoran modal, pembagian keuntungan dan kerugian, serta kewenangan mengelola','Menentukan akad yang tepat untuk ketiga kegiatan koperasi disertai alasan yang berkaitan dengan ciri setiap akad','Mengevaluasi rencana penyewaan tenda untuk kegiatan yang mengandung kemaksiatan dengan kesimpulan tidak diperbolehkan beserta alasannya','Menyusun langkah yang dapat dilakukan koperasi untuk mencegah penyalahgunaan barang sewaan melalui syarat dalam akad'],explanation:'Jawaban dinilai dari ketepatan perbandingan lima akad, ketepatan penentuan akad untuk setiap kegiatan, dan ketajaman evaluasi terhadap rencana penyewaan. Siswa yang tidak membedakan mudharabah dan musyarakah dari segi penyetoran modal belum mencapai taraf analisis yang diminta.'},
{level:'HOTS',indicator:'Menganalisis kedudukan kejujuran dalam perdagangan lalu menyusun penerapan etika berwirausaha',text:'Seorang pedagang di pasar tradisional dikenal selalu menepati timbangan, menjelaskan cacat barang kepada pembeli, dan mencatat setiap transaksi yang tidak tunai dalam buku pembukuan sehingga usahanya berkembang dan dipercaya oleh warga. Analisislah dua kedudukan kejujuran dan pencatatan transaksi dalam perdagangan beserta pengaruhnya terhadap keberkahan usaha, hubungkanlah analisis itu dengan hikmah dilarangnya riba dalam muamalah, lalu susunlah tiga penerapan etika berdagang yang dapat dipraktikkan oleh siswa madrasah yang berwirausaha di lingkungan sekolahnya!',key:'Kedudukan pertama, kejujuran dalam perdagangan: kejujuran mencakup menepati takaran dan timbangan, menjelaskan cacat barang kepada pembeli, dan tidak menyampaikan keterangan yang menyesatkan tentang mutu barang, sehingga kejujuran berkedudukan sebagai penentu keberkahan transaksi karena kedua pihak memperoleh haknya tanpa kerugian yang tersembunyi; pengaruhnya terhadap usaha adalah timbulnya kepercayaan dari pembeli yang menjadikan mereka kembali berbelanja dan menyampaikan keterangan baik kepada pihak lain, sehingga keuntungan yang diperoleh bersifat bertahan dan tidak bergantung pada penipuan yang suatu saat terbongkar. Kedudukan kedua, pencatatan transaksi: pencatatan transaksi yang tidak tunai berkedudukan sebagai penjagaan hak kedua pihak karena catatan menjadi alat pembuktian tentang jumlah, waktu, dan syarat pembayaran apabila terjadi perselisihan, dan pengaruhnya terhadap usaha adalah tertibnya pengelolaan sehingga pedagang mengetahui keadaan piutangnya, dapat menagih pada waktunya, dan tidak kehilangan haknya karena lupa; pencatatan juga menjadikan pedagang mampu menghitung keuntungan dengan tepat sehingga keputusan usahanya didasarkan pada keterangan yang benar. Hubungan dengan hikmah dilarangnya riba: riba dilarang karena menghasilkan tambahan harta tanpa pertukaran yang sepadan dan memindahkan keuntungan kepada pemilik modal dengan mengorbankan pihak yang memerlukan, sehingga hubungan keduanya terletak pada prinsip keadilan dalam memperoleh harta yaitu kejujuran dan pencatatan menjaga keadilan dalam pertukaran barang dan jasa sedangkan larangan riba menjaga keadilan dalam pertukaran harta dengan harta; keduanya bersama-sama mencegah timbulnya keuntungan yang diperoleh dari kerugian atau kesulitan pihak lain dan menjadikan muamalah berfungsi sebagai sarana tolong-menolong. Tiga penerapan etika berdagang bagi siswa yang berwirausaha di sekolah: pertama, menetapkan harga yang wajar dan menjelaskan keadaan barang secara jujur termasuk kekurangan barang buatan sendiri sehingga pembeli memperoleh keterangan yang benar dan tidak merasa tertipu sesudah membeli; kedua, mencatat setiap transaksi baik tunai maupun tidak tunai beserta nama teman yang berutang dan waktu pembayarannya, serta tidak menagih dengan cara yang merendahkan sehingga haknya terjaga dan hubungan pertemanan tetap baik; ketiga, menyisihkan sebagian keuntungan untuk sedekah atau untuk kegiatan sosial madrasah dan tidak menjual barang yang membahayakan kesehatan teman walaupun keuntungannya besar, sehingga usahanya tidak hanya menghasilkan harta melainkan juga manfaat bagi lingkungannya.',rubric:['Menganalisis kedudukan kejujuran dalam perdagangan beserta pengaruhnya terhadap keberkahan dan perkembangan usaha','Menganalisis kedudukan pencatatan transaksi sebagai penjagaan hak kedua pihak dan penertiban pengelolaan usaha','Menghubungkan kedua analisis dengan hikmah dilarangnya riba melalui prinsip keadilan dalam memperoleh harta','Menyusun tiga penerapan etika berdagang yang realistis bagi siswa, mencakup kejujuran harga, pencatatan, dan kepedulian sosial'],explanation:'Jawaban dinilai dari kedalaman analisis kedua kedudukan, ketepatan penghubungannya dengan hikmah larangan riba, dan kepraktisan tiga penerapan bagi siswa. Siswa yang hanya menyebutkan manfaat kejujuran tanpa menghubungkannya dengan prinsip keadilan belum mencapai taraf analisis yang diminta.'},
{level:'HOTS',indicator:'Mengevaluasi empat praktik perdagangan daring lalu menyimpulkan prinsip penilaian',text:'Seorang pengusaha muda menjalankan usahanya dengan empat cara: menjadi perantara yang menjual barang milik pihak lain sebelum ia membeli dan memilikinya, menerima pesanan barang yang diproduksi sesudah pembayaran diterima dengan spesifikasi yang jelas, mengadakan undian berhadiah bagi pembeli dengan nilai tertentu, dan menjual barang dengan pembayaran cicilan yang disertai denda keterlambatan yang bertambah setiap bulan. Evaluasilah keempat cara itu dengan menentukan hukumnya beserta alasannya, lalu simpulkanlah dua prinsip yang dapat digunakan untuk menilai praktik perdagangan baru pada masa sekarang!',key:'Evaluasi cara pertama: menjadi perantara yang menjual barang milik pihak lain sebelum membeli dan memilikinya tidak diperbolehkan karena menjual barang yang belum dimiliki dan belum berada dalam tanggungannya mengandung ketidakpastian penyerahan sehingga pembeli berisiko tidak memperoleh barangnya; yang seharusnya dilakukan adalah membeli barang itu terlebih dahulu atau menggunakan akad salam dengan spesifikasi dan waktu penyerahan yang jelas, atau menjadi wakil penjual yang memperoleh komisi atas nama pemilik barang. Evaluasi cara kedua: menerima pesanan barang yang diproduksi sesudah pembayaran diterima dengan spesifikasi yang jelas termasuk akad salam yang diperbolehkan karena jenis, sifat, jumlah, dan waktu penyerahan barang telah ditentukan sehingga ketidakadaan barang ketika akad tidak membatalkannya; praktik ini sah selama waktu penyerahan ditepati dan barang yang diserahkan sesuai dengan spesifikasi yang disepakati. Evaluasi cara ketiga: mengadakan undian berhadiah bagi pembeli dengan nilai tertentu perlu diperhatikan bentuknya, karena apabila hadiah itu berasal dari tambahan harga barang yang dibayar oleh pembeli sehingga pembeli menanggung biaya hadiah yang diundikan, praktik itu mengandung unsur perjudian dan tidak diperbolehkan; sebaliknya apabila hadiah diberikan oleh penjual dari hartanya sendiri tanpa menaikkan harga barang dan tanpa kewajiban tambahan bagi pembeli, praktik itu termasuk pemberian yang diperbolehkan sebagai bentuk promosi. Evaluasi cara keempat: menjual barang dengan pembayaran cicilan disertai denda keterlambatan yang bertambah setiap bulan tidak diperbolehkan karena tambahan yang timbul dari penundaan pembayaran merupakan riba, sedangkan jual beli cicilan dengan harga yang lebih tinggi dari harga tunai sah selama harga itu disepakati pada awal akad dan tidak bertambah karena keterlambatan; yang dapat dilakukan adalah menetapkan harga cicilan secara tetap pada awal akad atau menahan barang sebagai jaminan tanpa mengenakan tambahan atas penundaan. Dua prinsip penilaian praktik perdagangan baru: pertama, prinsip kejelasan objek dan kewenangan, yaitu praktik diperbolehkan selama barang atau manfaat yang diperjualbelikan jelas sifat, jumlah, dan waktu penyerahannya serta pihak yang menjual memiliki barang itu atau kewenangan untuk menjualnya sehingga tidak terdapat ketidakpastian yang merugikan salah satu pihak; kedua, prinsip bebas dari riba, judi, dan penipuan, yaitu praktik diperbolehkan selama tidak terdapat tambahan yang timbul dari penundaan pembayaran, tidak terdapat pertaruhan harta yang hasilnya bergantung pada keberuntungan, dan tidak terdapat keterangan yang menyesatkan pihak lain sehingga keuntungan diperoleh dari usaha dan pertukaran yang nyata.',rubric:['Mengevaluasi cara pertama dan kedua dengan menentukan hukum beserta alasannya yang berkaitan dengan kepemilikan barang dan akad salam','Mengevaluasi cara ketiga dengan membedakan undian yang biayanya dibebankan kepada pembeli dan hadiah yang berasal dari harta penjual','Mengevaluasi cara keempat dengan menjelaskan kedudukan denda keterlambatan sebagai riba dan cara yang dapat dilakukan sebagai pengganti','Menyimpulkan dua prinsip penilaian yang mencakup keempat praktik dan dapat diterapkan pada bentuk perdagangan baru'],explanation:'Jawaban dinilai dari ketepatan hukum setiap cara, ketajaman pembedaan pada kasus undian berhadiah, dan keterpaduan dua prinsip yang disimpulkan. Siswa yang menyimpulkan seluruh cara diperbolehkan karena lazim dilakukan belum menunjukkan kemampuan evaluasi berdasarkan ketentuan muamalah.'}
]
});
